#!/usr/bin/env python3
"""Persistent study tasks exposed as MCP tools. Dates use Europe/Moscow."""
from datetime import date, datetime
import os
from pathlib import Path
import re
import sqlite3
import sys
from zoneinfo import ZoneInfo

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from stdio import serve

ROOT = Path(__file__).resolve().parents[4]
STATUSES = ("todo", "in_progress", "done")


def text(value, field):
    if not isinstance(value, str) or not value.strip() or len(value) > 500:
        raise ValueError(f"{field}: expected non-empty text, at most 500 characters")
    return value.strip()


def parse_date(value):
    if not isinstance(value, str) or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", value):
        raise ValueError("Date must use YYYY-MM-DD")
    return date.fromisoformat(value)


def database():
    path = Path(os.environ.get("STUDY_TRACKER_DB", str(ROOT / "practices/practice_04/mcp/study_tracker/data/tasks.sqlite3")))
    path.parent.mkdir(parents=True, exist_ok=True)
    connection = sqlite3.connect(path)
    connection.row_factory = sqlite3.Row
    connection.execute("""CREATE TABLE IF NOT EXISTS tasks (
        id INTEGER PRIMARY KEY, title TEXT NOT NULL, course TEXT NOT NULL,
        deadline TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'todo',
        created_at TEXT NOT NULL)""")
    return connection


def task_view(row, today=None):
    today = today or datetime.now(ZoneInfo("Europe/Moscow")).date()
    task = dict(row)
    task["days_left"] = (date.fromisoformat(task["deadline"]) - today).days
    task["overdue"] = task["days_left"] < 0 and task["status"] != "done"
    return task


def add_task(title, course, deadline):
    title, course = text(title, "title"), text(course, "course")
    deadline = parse_date(deadline).isoformat()
    connection = database()
    try:
        with connection:
            cursor = connection.execute(
                "INSERT INTO tasks (title, course, deadline, created_at) VALUES (?, ?, ?, ?)",
                (title, course, deadline, datetime.now(ZoneInfo("Europe/Moscow")).isoformat()))
            return task_view(connection.execute("SELECT * FROM tasks WHERE id = ?", (cursor.lastrowid,)).fetchone())
    finally:
        connection.close()


def list_tasks(course=None, status=None):
    conditions, values = [], []
    if course is not None:
        conditions.append("course = ?")
        values.append(text(course, "course"))
    if status is not None:
        if status not in STATUSES:
            raise ValueError("status must be todo, in_progress or done")
        conditions.append("status = ?")
        values.append(status)
    connection = database()
    try:
        query = "SELECT * FROM tasks" + (" WHERE " + " AND ".join(conditions) if conditions else "")
        rows = connection.execute(query + " ORDER BY deadline, id", values).fetchall()
        return {"tasks": [task_view(row) for row in rows], "count": len(rows)}
    finally:
        connection.close()


def update_task_status(task_id, status):
    if type(task_id) is not int or task_id < 1:
        raise ValueError("task_id must be a positive integer")
    if status not in STATUSES:
        raise ValueError("status must be todo, in_progress or done")
    connection = database()
    try:
        with connection:
            if connection.execute("UPDATE tasks SET status = ? WHERE id = ?", (status, task_id)).rowcount == 0:
                raise ValueError(f"Task {task_id} not found")
            return task_view(connection.execute("SELECT * FROM tasks WHERE id = ?", (task_id,)).fetchone())
    finally:
        connection.close()


def study_dashboard(as_of=None):
    today = parse_date(as_of) if as_of is not None else datetime.now(ZoneInfo("Europe/Moscow")).date()
    tasks = [task_view(task, today) for task in list_tasks()["tasks"]]
    counts = {status: sum(task["status"] == status for task in tasks) for status in STATUSES}
    active = [task for task in tasks if task["status"] != "done"]
    return {"as_of": today.isoformat(), "timezone": "Europe/Moscow", "total": len(tasks),
            "by_status": counts, "progress_percent": round(100 * counts["done"] / len(tasks), 1) if tasks else 0,
            "overdue": [task for task in active if task["overdue"]],
            "due_soon": [task for task in active if 0 <= task["days_left"] <= 7],
            "next_task": active[0] if active else None}


def tool(name, description, properties, required=(), readonly=True):
    return {"name": name, "description": description,
            "inputSchema": {"type": "object", "properties": properties,
                            "required": list(required), "additionalProperties": False},
            "annotations": {"readOnlyHint": readonly, "destructiveHint": False, "openWorldHint": False}}


STRING = {"type": "string"}
STATUS = {"type": "string", "enum": list(STATUSES)}
TOOLS = [
    tool("add_task", "Добавить учебное задание; сохраняет данные в SQLite. Дедлайн YYYY-MM-DD.",
         {"title": STRING, "course": STRING, "deadline": STRING}, ("title", "course", "deadline"), False),
    tool("list_tasks", "Показать задания по дедлайну, можно фильтровать по курсу и статусу.",
         {"course": STRING, "status": STATUS}),
    tool("update_task_status", "Изменить статус существующего задания по ID.",
         {"task_id": {"type": "integer", "minimum": 1}, "status": STATUS}, ("task_id", "status"), False),
    tool("study_dashboard", "Сводка прогресса, просроченные задания, дедлайны на 7 дней и следующая задача.",
         {"as_of": {"type": "string", "description": "Дата YYYY-MM-DD; по умолчанию сегодня в Москве"}}),
]

if __name__ == "__main__":
    serve("study-tracker", TOOLS, {item["name"]: globals()[item["name"]] for item in TOOLS})

#!/usr/bin/env python3
"""HTTP bridge to the existing MCP server; no direct database access."""
import argparse
from datetime import datetime, timedelta
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import mimetypes
import os
from pathlib import Path
import sys
import tempfile
from threading import Lock
from urllib.parse import parse_qs, urlparse
from zoneinfo import ZoneInfo

ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT / "practices/practice_04/mcp"))
from client import Client

SERVER = "practices/practice_04/mcp/study_tracker/server.py"
TOOLS = {"add_task", "list_tasks", "update_task_status", "study_dashboard"}
DIST = ROOT / "practices/practice_04/dashboard/dist"


class Bridge:
    def __init__(self, demo_path):
        self.demo_path = str(demo_path)
        self.demo_ready = False
        self.lock = Lock()
        self.history = []
        self.log = ROOT / "practices/practice_04/mcp/study_tracker/data/dashboard-calls.jsonl"

    def environment(self, mode):
        return dict(os.environ, STUDY_TRACKER_DB=self.demo_path) if mode == "demo" else dict(os.environ)

    def call(self, client, mode, name, arguments):
        result = client.call(name, **arguments)
        entry = {"time": datetime.now(ZoneInfo("Europe/Moscow")).isoformat(),
                 "mode": mode, "tool": name, "arguments": arguments, "result": result}
        self.history.append(entry)
        self.history = self.history[-50:]
        self.log.parent.mkdir(parents=True, exist_ok=True)
        with self.log.open("a", encoding="utf-8") as stream:
            stream.write(json.dumps(entry, ensure_ascii=False) + "\n")
        return result

    def seed(self, client):
        if self.demo_ready:
            return
        today = datetime.now(ZoneInfo("Europe/Moscow")).date()
        examples = [
            ("Подготовить защиту практики 4", "Технологии ИИ", 2, "in_progress"),
            ("Написать свободную рефлексию", "Технологии ИИ", -1, "todo"),
            ("Решить задачи по интегралам", "Математика", 0, "todo"),
            ("Оформить лабораторную работу", "Базы данных", 5, "in_progress"),
            ("Изучить протокол MCP", "Технологии ИИ", -2, "done"),
            ("Сдать домашнее задание", "Математика", 8, "done"),
        ]
        for title, course, delta, status in examples:
            result = self.call(client, "demo", "add_task", {
                "title": title, "course": course, "deadline": (today + timedelta(days=delta)).isoformat()})
            task = self.decode(result)
            if status != "todo":
                self.decode(self.call(client, "demo", "update_task_status", {"task_id": task["id"], "status": status}))
        self.demo_ready = True

    @staticmethod
    def decode(result):
        if result.get("isError"):
            raise ValueError(result["content"][0]["text"])
        return json.loads(result["content"][0]["text"])

    def execute(self, mode, name=None, arguments=None):
        with self.lock, Client(SERVER, self.environment(mode)) as client:
            if mode == "demo":
                self.seed(client)
            if name:
                return self.call(client, mode, name, arguments)
            tasks = self.decode(self.call(client, mode, "list_tasks", {}))
            dashboard = self.decode(self.call(client, mode, "study_dashboard", {}))
            return {"tasks": tasks["tasks"], "dashboard": dashboard,
                    "mode": mode, "history": [entry for entry in self.history if entry["mode"] == mode][-12:]}


class Handler(BaseHTTPRequestHandler):
    def log_message(self, *_):
        pass

    def send_json(self, value, status=200):
        body = json.dumps(value, ensure_ascii=False).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.end_headers()
        self.wfile.write(body)

    def authorized(self):
        host = self.headers.get("Host", "")
        if host not in {f"127.0.0.1:{self.server.server_port}", f"localhost:{self.server.server_port}"}:
            self.send_json({"error": "Invalid host"}, 403)
            return False
        origin = self.headers.get("Origin")
        allowed = {f"http://{host}", "http://127.0.0.1:5173", "http://localhost:5173"}
        if origin and origin not in allowed:
            self.send_json({"error": "Invalid origin"}, 403)
            return False
        return True

    def mode(self):
        mode = parse_qs(urlparse(self.path).query).get("mode", ["real"])[0]
        if mode not in {"demo", "real"}:
            raise ValueError("mode must be demo or real")
        return mode

    def do_GET(self):
        if not self.authorized():
            return
        path = urlparse(self.path).path
        if path == "/api/state":
            try:
                self.send_json(self.server.bridge.execute(self.mode()))
            except ValueError as exc:
                self.send_json({"error": str(exc)}, 400)
            except (OSError, RuntimeError, TimeoutError) as exc:
                self.send_json({"error": f"MCP unavailable: {exc}"}, 502)
            return
        files = {"/": DIST / "index.html", "/index.html": DIST / "index.html"}
        asset = (DIST / path.lstrip("/")).resolve()
        if path.startswith("/assets/") and asset.is_relative_to(DIST.resolve()):
            files[path] = asset
        if path not in files or not files[path].is_file():
            self.send_json({"error": "Not found; build the React app with npm --prefix practices/practice_04/dashboard run build"}, 404)
            return
        body = files[path].read_bytes()
        self.send_response(200)
        self.send_header("Content-Type", mimetypes.guess_type(str(files[path]))[0] or "application/octet-stream")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("X-Content-Type-Options", "nosniff")
        self.end_headers()
        self.wfile.write(body)

    def do_POST(self):
        if not self.authorized():
            return
        path = urlparse(self.path).path
        name = path.removeprefix("/api/tools/")
        if not path.startswith("/api/tools/") or name not in TOOLS:
            self.send_json({"error": "Unknown tool"}, 404)
            return
        try:
            length = int(self.headers.get("Content-Length", "0"))
            if not 0 < length <= 16384:
                raise ValueError("Expected a JSON body up to 16 KB")
            if self.headers.get("Content-Type", "").split(";")[0] != "application/json":
                raise ValueError("Content-Type must be application/json")
            arguments = json.loads(self.rfile.read(length))
            if not isinstance(arguments, dict):
                raise ValueError("Arguments must be an object")
            result = self.server.bridge.execute(self.mode(), name, arguments)
            self.send_json(result, 400 if result.get("isError") else 200)
        except ValueError as exc:
            self.send_json({"error": str(exc)}, 400)
        except (OSError, RuntimeError, TimeoutError) as exc:
            self.send_json({"error": f"MCP unavailable: {exc}"}, 502)


def create_server(port, demo_path):
    server = ThreadingHTTPServer(("127.0.0.1", port), Handler)
    server.bridge = Bridge(demo_path)
    return server


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--port", type=int, default=8765)
    args = parser.parse_args()
    with tempfile.TemporaryDirectory(prefix="study-dashboard-") as directory:
        server = create_server(args.port, Path(directory) / "demo.sqlite3")
        print(f"Study Space: http://127.0.0.1:{server.server_port}", flush=True)
        try:
            server.serve_forever()
        except KeyboardInterrupt:
            pass
        finally:
            server.server_close()

